    }

    @media (max-width: 480px) {
      .card {
        padding: 1.4rem;
        border-radius: 1.15rem;
      }
    }

    @media (prefers-color-scheme: dark) {
      :root {
        --bg: #0b1120;
        --surface: rgba(12, 18, 32, 0.9);
        --surface-strong: #101827;
        --text: #f3f7ff;
        --muted: #b5c0d4;
        --border: #34425c;
        --border-strong: #8ab4ff;
        --accent: #8ab4ff;
        --accent-strong: #b7d0ff;
        --success-bg: #123321;
        --success-text: #aff0c5;
        --error-bg: #391919;
        --error-text: #ffb4ab;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
      }

      .eyebrow {
        background: rgba(138, 180, 255, 0.16);
      }

      .form-field {
        background: rgba(16, 24, 39, 0.74);
      }
    }

    @media (forced-colors: active) {
      .card,
