    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Product setup</p>
      <h1 id="page-title">Review and confirm</h1>
      <p class="intro">Agree to the terms of use to continue with your account setup.</p>

      <form id="consent-form" novalidate>
        <div class="form-field" data-invalid="false">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="consent-help consent-error"
            >
            <label for="consent">
