    const checkbox = document.getElementById("consent");
    const field = document.querySelector(".form-field");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    function setInvalidState(isInvalid) {
      field.dataset.invalid = String(isInvalid);
      checkbox.setAttribute("aria-invalid", String(isInvalid));
      error.hidden = !isInvalid;
    }

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        setInvalidState(false);
        status.textContent = "";
        status.dataset.state = "";
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        setInvalidState(true);
        status.textContent = "";
        status.dataset.state = "";
        checkbox.focus();
        return;
      }

      setInvalidState(false);
      status.textContent = "Consent recorded. You can move to the next step.";
      status.dataset.state = "success";
    });
