<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content" tabindex="-1">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Product setup</p>
      <h1 id="page-title">Review and confirm</h1>
      <p class="intro">Agree to the terms of use to continue with your account setup.</p>

      <form id="consent-form" novalidate>
        <div class="form-field" data-invalid="false">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="consent-help consent-error"
            >
            <label for="consent">
              I agree to the terms of use
              <span class="required-mark" aria-hidden="true">*</span>
            </label>
          </div>
          <p id="consent-help" class="helper-text">Required to finish creating your access.</p>
          <p id="consent-error" class="error-text" hidden>Error: You must agree to the terms of use before continuing.</p>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>

        <p id="form-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("consent");
    const field = document.querySelector(".form-field");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    function setInvalidState(isInvalid) {
      field.dataset.invalid = String(isInvalid);
      checkbox.setAttribute("aria-invalid", String(isInvalid));
      error.hidden = !isInvalid;
    }

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        setInvalidState(false);
        status.textContent = "";
        status.dataset.state = "";
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        setInvalidState(true);
        status.textContent = "";
        status.dataset.state = "";
        checkbox.focus();
        return;
      }

      setInvalidState(false);
      status.textContent = "Consent recorded. You can move to the next step.";
      status.dataset.state = "success";
    });
  </script>
</body>
</html>
